/* Hand-written picolibc configuration for the DMA machine target
 * (normally generated by picolibc's meson build). Integer-only stdio,
 * no floats, no long long, no locking, no TLS — matching the dmacc v0
 * subset (prompts/007, 008). */
#ifndef _PICOLIBC_H_
#define _PICOLIBC_H_

#define __PICOLIBC__ 1

/* printf/scanf family: integer variant is the default. */
#define __IO_DEFAULT 'i'

#endif /* _PICOLIBC_H_ */
